// Game based on IDEA.md – Orb Escape
// Targets <canvas id="game"></canvas>

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  // Resize to fill parent or set a default size
  const resize = () => {
    canvas.width = canvas.clientWidth || 800;
    canvas.height = canvas.clientHeight || 600;
  };
  resize();
  window.addEventListener('resize', resize);

  // ----- Input handling -----
  const keys = {};
  window.addEventListener('keydown', e => (keys[e.key] = true));
  window.addEventListener('keyup', e => (keys[e.key] = false));

  // ----- Entities -----
  const player = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    size: 12, // length of triangle side
    speed: 3,
    draw() {
      ctx.fillStyle = '#0ff';
      ctx.beginPath();
      ctx.moveTo(this.x, this.y - this.size);
      ctx.lineTo(this.x - this.size, this.y + this.size);
      ctx.lineTo(this.x + this.size, this.y + this.size);
      ctx.closePath();
      ctx.fill();
    },
    update() {
      if (keys['ArrowUp']) this.y -= this.speed;
      if (keys['ArrowDown']) this.y += this.speed;
      if (keys['ArrowLeft']) this.x -= this.speed;
      if (keys['ArrowRight']) this.x += this.speed;
      // keep inside bounds
      this.x = Math.max(0, Math.min(canvas.width, this.x));
      this.y = Math.max(0, Math.min(canvas.height, this.y));
    },
  };

  const orbs = [];
  const coins = [];

  let score = 0;
  let gameOver = false;

  // ----- Helper functions -----
  const rand = (min, max) => Math.random() * (max - min) + min;
  const distance = (x1, y1, x2, y2) => Math.hypot(x1 - x2, y1 - y2);

  const spawnOrb = () => {
    // spawn at random edge
    const edge = Math.floor(rand(0, 4)); // 0 top,1 right,2 bottom,3 left
    let x, y, vx, vy;
    const speed = rand(0.5, 1.5);
    const radius = rand(10, 20);
    if (edge === 0) { // top
      x = rand(0, canvas.width);
      y = -radius;
      vx = rand(-1, 1) * speed;
      vy = speed;
    } else if (edge === 1) { // right
      x = canvas.width + radius;
      y = rand(0, canvas.height);
      vx = -speed;
      vy = rand(-1, 1) * speed;
    } else if (edge === 2) { // bottom
      x = rand(0, canvas.width);
      y = canvas.height + radius;
      vx = rand(-1, 1) * speed;
      vy = -speed;
    } else { // left
      x = -radius;
      y = rand(0, canvas.height);
      vx = speed;
      vy = rand(-1, 1) * speed;
    }
    orbs.push({ x, y, vx, vy, radius, growth: rand(0.05, 0.15) });
  };

  const spawnCoin = () => {
    const radius = 8;
    const x = rand(radius, canvas.width - radius);
    const y = rand(radius, canvas.height - radius);
    coins.push({ x, y, radius });
  };

  // initial spawns
  for (let i = 0; i < 5; i++) spawnOrb();
  for (let i = 0; i < 3; i++) spawnCoin();

  // ----- Game Loop -----
  const update = () => {
    if (gameOver) return;
    player.update();

    // update orbs
    for (let i = orbs.length - 1; i >= 0; i--) {
      const o = orbs[i];
      o.x += o.vx;
      o.y += o.vy;
      o.radius += o.growth;
      // remove if out of screen far enough
      if (o.x < -100 || o.x > canvas.width + 100 || o.y < -100 || o.y > canvas.height + 100) {
        orbs.splice(i, 1);
        spawnOrb();
      }
    }

    // coin collection
    for (let i = coins.length - 1; i >= 0; i--) {
      const c = coins[i];
      if (distance(player.x, player.y, c.x, c.y) < c.radius + player.size) {
        score++;
        coins.splice(i, 1);
        spawnCoin();
      }
    }

    // collision with orbs -> game over
    for (const o of orbs) {
      if (distance(player.x, player.y, o.x, o.y) < o.radius + player.size) {
        gameOver = true;
        break;
      }
    }
  };

  const draw = () => {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // draw orbs
    ctx.fillStyle = 'rgba(255,0,0,0.5)';
    for (const o of orbs) {
      ctx.beginPath();
      ctx.arc(o.x, o.y, o.radius, 0, Math.PI * 2);
      ctx.fill();
    }
    // draw coins
    ctx.fillStyle = 'gold';
    for (const c of coins) {
      ctx.beginPath();
      ctx.arc(c.x, c.y, c.radius, 0, Math.PI * 2);
      ctx.fill();
    }
    // draw player
    player.draw();
    // draw score
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Score: ${score}`, 10, 20);
    // game over overlay
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#f00';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2 - 20);
      ctx.font = '24px sans-serif';
      ctx.fillText('Press R to restart', canvas.width / 2, canvas.height / 2 + 30);
    }
  };

  const loop = () => {
    update();
    draw();
    requestAnimationFrame(loop);
  };
  requestAnimationFrame(loop);

  // restart handler
  window.addEventListener('keydown', e => {
    if (gameOver && e.key.toLowerCase() === 'r') {
      // reset state
      score = 0;
      gameOver = false;
      player.x = canvas.width / 2;
      player.y = canvas.height / 2;
      orbs.length = 0;
      coins.length = 0;
      for (let i = 0; i < 5; i++) spawnOrb();
      for (let i = 0; i < 3; i++) spawnCoin();
    }
  });
})();
